import { test, expect } from '@playwright/test';

test.describe('Success Toast Notification on Record Save', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should display success toast notification with success message and close button when record is saved successfully', async ({ page }) => {
    // Intercept the save API call
    await page.route('**/api/records/save', (route) => {
      route.continue();
    });

    // Locate and click the save button using getByRole
    const saveButton = page.getByRole('button', { name: /save record/i });
    await saveButton.click();

    // Wait for the toast to appear using getByRole
    const successToast = page.getByRole('alert', { name: /record saved successfully/i });
    await expect(successToast).toBeVisible();

    // Verify success message is present using getByText
    const successMessage = page.getByText(/record saved successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify close button is present using getByRole
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify toast is visible using getByRole
    await expect(successToast).toBeVisible();

    // Verify toast is dismissible using getByRole
    await expect(closeButton).toBeEnabled();

    // Verify success toast has a positive class
    const successClass = page.getByTestId('success-toast');
    await expect(successClass).toHaveClass(/success/i);

    // Verify toast has a dismiss button using getByRole
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();

    // Verify toast is not persistent
    await expect(successToast).not.toBeVisible();
  });

  test('should not display success toast notification when record save fails', async ({ page }) => {
    // Intercept the save API call with a failure response
    await page.route('**/api/records/save', (route) => {
      route.abort('Failed to save record');
    });

    // Locate and click the save button using getByRole
    const saveButton = page.getByRole('button', { name: /save record/i });
    await saveButton.click();

    // Wait for error toast to appear using getByRole
    const errorToast = page.getByRole('alert', { name: /failed to save record/i });
    await expect(errorToast).toBeVisible();

    // Verify error message is present using getByText
    const errorMessage = page.getByText(/failed to save record/i);
    await expect(errorMessage).toBeVisible();

    // Verify error toast is dismissible using getByRole
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();

    // Verify error toast has a negative class
    const errorClass = page.getByTestId('error-toast');
    await expect(errorClass).toHaveClass(/error/i);

    // Verify error toast is not persistent
    await expect(errorToast).not.toBeVisible();
  });
});
